light.example:
import {defineShader, p, light, compose, math, transformColor, transformPosition} from 'shaders/std'

const {radialFrame, withFrame, modulate, glowPoint, softRayLobes, featherMask} = light

// A sun: soft rays spinning around a draggable center, feathered at a radius, drawn as emitted light.
export const Sun = defineShader({
  name: 'Sun',
  animatedTime: {speed: 'speed'},
  props: {
    center: {default: {x: 0.5, y: 0.5}, transform: transformPosition},
    color: {default: '#ffd27a', transform: transformColor},
    radius: {default: 0.5},
    rays: {default: 12},
    softness: {default: 0.6},
    speed: {default: 1},
  },
  paint: (params) => {
    const coverage = withFrame(
      radialFrame(p('center')),
      modulate(softRayLobes({count: p('rays'), softness: p('softness'), spin: 0.2}), glowPoint({sharpness: 6}), featherMask({radius: p('radius'), feather: 0.4})),
      'sun',
    )(params)
    const rgb = math.mul(params.uniforms.color.member('rgb'), coverage)
    return compose.emissiveAlpha(rgb)
  },
})

materials.example:
import {defineShader, p, uniformOf, paint, frames, materials, compose, math, transformColor, transformColorSpace, colorSpaceOptions} from 'shaders/std'

const {add, mul, dot, vec3, vec4} = math
const {noiseField, warped, scaledVolume, tone, pair} = paint
const {surfaceOf, direction} = frames
const {fdSlope, nudgeNormal, keyLightAt, lambert, dualLobeGlint, neutralTone} = materials

// One height field drives everything: warped noise on a zoomable slab.
const height = scaledVolume(
  warped(noiseField('mx3'), {amount: p('warp'), amountScale: 4, timeScale: 0.12}),
  {scale: p('scale')},
)

// Silk: the field's slope becomes a normal, a key light shades it, a two-lobe sheen catches the folds.
export const SilkTide = defineShader({
  name: 'SilkTide',
  animatedTime: {speed: 'speed'},
  props: {
    colorA: {default: '#0b1026', transform: transformColor},
    colorB: {default: '#ff7e5f', transform: transformColor},
    colorSpace: {default: 'oklch', transform: transformColorSpace, compileTime: true, ui: {type: 'select', options: colorSpaceOptions}},
    highlight: {default: '#fff3dc', transform: transformColor},
    scale: {default: 1.8},
    warp: {default: 0.55},
    lightAngle: {default: 35},
    sheen: {default: 1},
    speed: {default: 1},
  },
  paint: (params) => {
    const {uv} = surfaceOf(params)
    const u = (name: string) => uniformOf(p(name), params)

    // 1 · the field and its slope: three taps of the noise, bound once
    const relief = fdSlope((at) => height(params, at), uv, 0.0035, 'tide')

    // 2 · color: tone-shape the field and read it through the two-color palette
    const shaped = tone(() => relief.value, {glow: 5, contrast: 1.3, balance: 50, invert: true})(params, uv)
    const base = pair(p('colorA'), p('colorB'), p('colorSpace'))(shaped, params)

    // 3 · light: slope → normal → key light → a wrapped diffuse and a sheen
    const tilt = mul(u('sheen'), -0.08)
    const n = nudgeNormal(vec3(0, 0, -1), mul(relief.dx, tilt), mul(relief.dy, tilt), 'tideN')
    const key = keyLightAt(direction(u('lightAngle'), 'tideDir'), -0.7, 'tideKey')
    const diffuse = add(0.55, mul(0.45, lambert(n, key.member('L'), {wrap: 0.5})))
    const spec = dualLobeGlint(dot(n, key.member('H')), {core: [140, 1], halo: [22, 0.15], gain: u('sheen')})

    const rgb = neutralTone(add(mul(base.member('rgb'), diffuse), mul(u('highlight').member('rgb'), spec)))
    return compose.dithered(vec4(rgb, base.member('a')), params)
  },
})

volume.example:
import {defineShader, animatedTime, materials, volume, math, transformColor, transformPosition} from 'shaders/std'

const {shapedSurface, surfaceField, viewRay, hashNoise, silhouette, guarded, insideShape} = materials
const {interiorRay, turbulentMedium, volumeMarch} = volume
const {float, local, mul, smoothstep, splat3, sub, vec4} = math

const STEPS = 6

// Smoke sealed inside any shape: a six-step march through billowing density, glowing in the smoke color.
export const Smoke = defineShader({
  name: 'Smoke',
  role: 'shapeEffect',
  species: 'custom',
  animatedTime: {speed: 'speed'},
  props: {
    center: {default: {x: 0.5, y: 0.5}, transform: transformPosition},
    scale: {default: 1},
    rotation: {default: 0},
    color: {default: '#ffb27a', transform: transformColor},
    density: {default: 1},
    gasScale: {default: 1},
    edgeSoftness: {default: 0.01},
    speed: {default: 1},
    shape: {default: JSON.stringify({type: 'sphere3D', radius: 0.35}), ui: {type: 'shape', label: 'Shape'}},
    shapeSdfUrl: {default: '', compileTime: true},
    shapeType: {default: '', compileTime: true},
  },
  ...shapedSurface({
    stencil: 'centre',
    centreTap: 'fast',
    surface: (frame, params) => {
      const u = params.uniforms
      const field = surfaceField(frame, params, {scale: u.scale})
      const view = viewRay(params, field)
      // The shape's own coordinates, centred, as the point the ray enters at.
      const origin = {x: sub(frame.sdfUV!.member('x'), 0.5), y: sub(frame.sdfUV!.member('y'), 0.5)}
      const ray = interiorRay(field, frame, {origin, view, shear: 0.5})
      const drift = local(mul(animatedTime(params), 0.15), 'drift')
      const jitter = mul(hashNoise(mul(origin.x, 311.7), mul(origin.y, 173.3)), 0.15 / STEPS)
      const march = volumeMarch(
        {steps: STEPS, entry: ray.entry, length: ray.length, jitter, emissionGain: float(4 / STEPS)},
        ({i, z}) => {
          const at = ray.at(z)
          const gas = turbulentMedium({x: at.x, y: at.y, z}, {frequency: mul(u.gasScale, 3), drift, billow: float(0.4), hint: `${i}`})
          const dens = local(smoothstep(0, 0.6, gas.density), `dens${i}`)
          return {emit: mul(u.color.member('rgb'), dens), absorb: splat3(mul(dens, mul(u.density, 3 / STEPS)))}
        },
      )
      const smoke = vec4(march.color, silhouette(field, u.edgeSoftness))
      return guarded(insideShape(field.sdf, field.pxH), smoke, vec4(0, 0, 0, 0), 'smoke')
    },
  }),
})

radiance.example:
import {defineShader, listPropConfig, materials, radiance, compose, math, transformColor, transformPosition} from 'shaders/std'

const {shapedSurface, surfaceField, silhouette, exposureTone} = materials
const {irradianceField} = radiance
const {emissiveAlpha} = compose
const {local, mix, splat3, vec4} = math

// One spec for both halves: the compute gather and the fragment read.
const GATHER = {
  rays: {burst: 128, motion: 64, refine: 32, refineFrames: 12},
  steps: 32,
  shadowSteps: 12,
  resolution: 512,
  lights: {prop: 'lights', position: 'position', color: 'color', intensity: 'intensity'},
  reach: 'reach',
  wrap: 'wrap',
  lightRange: 'lightRange',
  shadowSoftness: 'shadowSoftness',
}

// Colored lights spilling around a dark shape, gathered once and read per pixel.
export const LitEdge = defineShader({
  name: 'LitEdge',
  role: 'shapeEffect',
  species: 'custom',
  props: {
    center: {default: {x: 0.5, y: 0.5}, transform: transformPosition},
    scale: {default: 1},
    rotation: {default: 0},
    lights: listPropConfig({
      maxItems: 6,
      minItems: 1,
      itemLabel: 'Light',
      item: {
        position: {kind: 'position', default: {x: 0.3, y: 0.3}, label: 'Position'},
        color: {kind: 'color', default: '#ffb347', label: 'Color'},
        intensity: {kind: 'number', default: 3, label: 'Intensity', min: 0, max: 8, step: 0.01},
      },
    }, {
      default: [
        {position: {x: 0.3, y: 0.3}, color: '#ffb347', intensity: 3},
        {position: {x: 0.72, y: 0.7}, color: '#7a5cff', intensity: 2},
      ],
      description: 'The point lights striking the shape',
      label: 'Lights',
      group: 'Lights',
    }),
    lightRange: {default: 1.2},
    reach: {default: 3},
    wrap: {default: 0},
    shadowSoftness: {default: 0.2},
    bodyColor: {default: '#000000', transform: transformColor},
    edgeSoftness: {default: 0.01},
    shape: {default: JSON.stringify({type: 'circleSDF', radius: 0.35}), ui: {type: 'shape', label: 'Shape'}},
    shapeSdfUrl: {default: '', compileTime: true},
    shapeType: {default: '', compileTime: true},
  },
  ...shapedSurface({
    stencil: 'centre',
    centreTap: 'fast',
    surface: (frame, params) => {
      const u = params.uniforms
      const field = surfaceField(frame, params)
      const spill = irradianceField(GATHER).sample(params) ?? splat3(0)
      const glow = emissiveAlpha(exposureTone(spill), 'glow')
      const cov = local(silhouette(field, u.edgeSoftness), 'cov')
      return vec4(mix(glow.member('rgb'), u.bodyColor.member('rgb'), cov), mix(glow.member('a'), 1, cov))
    },
  }),
  compute: (params) => irradianceField(GATHER).compute(params),
})

voxels.example:
import {defineShader, p, materials, voxels, math, transformColor, transformPosition} from 'shaders/std'

const {lambert} = materials
const {voxelSurface} = voxels
const {add, cos, local, mix, mul, neg, normalize, sin, sub, vec3, vec4} = math

const DEG = Math.PI / 180

// Any shape as lit blocks: a key light you can orbit, shadows between the blocks, a sky fill in the creases.
export const Blocks = defineShader({
  name: 'Blocks',
  role: 'shapeEffect',
  species: 'custom',
  props: {
    center: {default: {x: 0.5, y: 0.5}, transform: transformPosition},
    scale: {default: 1},
    rotation: {default: 0},
    voxelSize: {default: 0.035},
    voxelShape: {default: 'cube', compileTime: true, ui: {type: 'select', options: [{label: 'Cube', value: 'cube'}, {label: 'Rounded', value: 'rounded'}, {label: 'Sphere', value: 'sphere'}]}},
    gridSpace: {default: 'shape', compileTime: true, ui: {type: 'select', options: [{label: 'Model', value: 'shape'}, {label: 'Screen', value: 'view'}]}},
    voxelScale: {default: 1},
    fill: {default: 0},
    bevel: {default: 0},
    depth: {default: 0.12},
    lightAngle: {default: 225},
    lightElevation: {default: 45},
    shadows: {default: 0.7},
    shadowSoftness: {default: 0.3},
    color: {default: '#e8a24a', transform: transformColor},
    sky: {default: '#6f86c9', transform: transformColor},
    shape: {default: JSON.stringify({type: 'sphere3D', radius: 0.35}), ui: {type: 'shape', label: 'Shape'}},
    shapeSdfUrl: {default: '', compileTime: true},
    shapeType: {default: '', compileTime: true},
  },
  ...voxelSurface({
    style: p('voxelShape'),
    gridSpace: p('gridSpace'),
    voxelSize: p('voxelSize'),
    fill: p('fill'),
    voxelScale: p('voxelScale'),
    bevel: p('bevel'),
    shadowSoftness: p('shadowSoftness'),
    lightAngle: p('lightAngle'),
    lightElevation: p('lightElevation'),
    depth: p('depth'),
    surface: (vox, _frame, params) => {
      const u = params.uniforms
      // The key light as a vector, from its angle around the canvas and its elevation.
      const az = mul(u.lightAngle, DEG)
      const el = mul(u.lightElevation, DEG)
      const L = local(normalize(vec3(mul(cos(az), cos(el)), mul(sin(az), cos(el)), neg(sin(el)))), 'L')
      // Key light, cut by the shadow other blocks cast; sky fill, darkened in the creases.
      const lit = sub(1, mul(vox.shadow, u.shadows))
      const key = mul(lambert(vox.normal, L, {wrap: 0.12}), lit)
      const fill = mul(u.sky.member('rgb'), mul(0.5, vox.ao))
      // A little per-block variation so the bricks read as individual.
      const tone = mix(0.85, 1.15, vox.cellHash)
      const rgb = mul(add(mul(u.color.member('rgb'), key), fill), tone)
      return vec4(rgb, vox.coverage)
    },
  }),
})

