import {defineShader, p, uniformOf, math, mask, frames, transformColor, transformPosition} from 'shaders/std'

const {add, sub, mul, div, clamp, local, vec4} = math

// Orb: a soft glowing disc with a crisp ring just outside it, over a transparent background.
export const Orb = defineShader({
  name: 'Orb',
  props: {
    center: {default: {x: 0.5, y: 0.5}, transform: transformPosition},
    color: {default: '#7dd3fc', transform: transformColor},
    ringColor: {default: '#ffffff', transform: transformColor},
    radius: {default: 0.2},
    softness: {default: 0.5},
  },
  paint: (params) => {
    const u = (name: string) => uniformOf(p(name), params)
    const surface = frames.surfaceOf(params)
    const {dist} = frames.centredFrame({center: p('center')})(params, surface)
    const px = div(1, surface.viewport.member('y')) // one device pixel, in uv
    const body = local(mask.softDisc({
      dist,
      radius: u('radius'),
      softness: {width: mul(u('softness'), 0.3), curve: add(mul(u('softness'), 2), 0.5)},
    }), 'body')
    // A signed distance to a circle a little larger than the orb: negative inside, zero on the ring.
    const ring = local(mask.crispStroke({distance: sub(dist, mul(u('radius'), 1.3)), width: 0.006, footprint: px}), 'ring')
    const rgb = add(mul(u('color').member('rgb'), body), mul(u('ringColor').member('rgb'), ring))
    return vec4(rgb, clamp(add(body, ring), 0, 1))
  },
})

math.example:
import {defineShader, p, uniformOf, animatedTime, math, frames, transformColor, transformPosition} from 'shaders/std'

const {add, sub, mul, sin, smoothstep, mix, splat3, local, vec4} = math

// Rings: concentric waves spreading from a draggable center, blended between two colors.
export const Rings = defineShader({
  name: 'Rings',
  animatedTime: {speed: 'speed'},
  props: {
    center: {default: {x: 0.5, y: 0.5}, transform: transformPosition},
    colorA: {default: '#0b1026', transform: transformColor},
    colorB: {default: '#7dd3fc', transform: transformColor},
    frequency: {default: 24},
    softness: {default: 0.25},
    speed: {default: 1},
  },
  paint: (params) => {
    const u = (name: string) => uniformOf(p(name), params)
    const {dist} = frames.centredFrame({center: p('center')})(params, frames.surfaceOf(params))
    // A −1..1 wave along the distance, moved into 0..1 and computed once.
    const wave = local(add(mul(sin(sub(mul(dist, u('frequency')), animatedTime(params))), 0.5), 0.5), 'wave')
    // softness 0 is a hard ring, 0.5 a smooth gradient between rings.
    const band = smoothstep(sub(0.5, u('softness')), add(0.5, u('softness')), wave)
    const rgb = mix(u('colorA').member('rgb'), u('colorB').member('rgb'), splat3(band))
    return vec4(rgb, 1)
  },
})

motion.example:
import {defineShader, p, uniformOf, animatedTime, math, motion, transformColor} from 'shaders/std'

const {sub, mul, mix, splat3, vec4} = math

// Flash: every `period` seconds the canvas lights up in a new random blend of two colors and fades out.
export const Flash = defineShader({
  name: 'Flash',
  animatedTime: {speed: 'speed'},
  props: {
    colorA: {default: '#ff7e5f', transform: transformColor},
    colorB: {default: '#7dd3fc', transform: transformColor},
    period: {default: 2},
    speed: {default: 1},
  },
  paint: (params) => {
    const u = (name: string) => uniformOf(p(name), params)
    const t = animatedTime(params)
    const {progress, index} = motion.cycle(t, u('period'))
    const fade = motion.easeOut(sub(1, progress)) // bright at the start of each pass, then out
    const pick = motion.cycleSeed(index) // one stable random blend per pass
    const breathe = motion.oscillate(t, {rate: 0.5, min: 0.7, max: 1})
    const rgb = mix(u('colorA').member('rgb'), u('colorB').member('rgb'), splat3(pick))
    return vec4(mul(rgb, mul(fade, breathe)), 1)
  },
})

