import {defineShader, p, sim, transformColor, transformPosition} from 'shaders/std'
import {tgpu, d} from '@coreroot/gpu/kit'
import {buildStableFluidsKernels, buildEmitterSplatKernel, buildFluidOutputKernel, mixExpr, vec4, ZERO} from '@coreroot/gpu/porters'
import type {GpuFragmentParams, KitTexture, Expr} from '@coreroot/gpu/porters'

const {fluidSim, splat} = sim.fluids

const N = 256
const COUNT = N * N

// The values every pass reads each frame. dt, curlStrength, velFade, dyeFade and colorDecay are the
// solver's; the rest drive the emitter and the cursor shove.
const FluidParams = d.struct({
  dt: d.f32, emitX: d.f32, emitY: d.f32, emitVelX: d.f32, emitVelY: d.f32,
  perpDirX: d.f32, perpDirY: d.f32, spreadFactor: d.f32, emitRad: d.f32, emitIntensity: d.f32,
  dyeFade: d.f32, velFade: d.f32, curlStrength: d.f32, gravity: d.f32, cursorX: d.f32, cursorY: d.f32,
  cursorVelX: d.f32, cursorVelY: d.f32, mouseActive: d.f32, mouseRadSq: d.f32, colorDecay: d.f32,
})
// The fluid's buffers, by the names the solver expects.
const fluidLayout = tgpu.bindGroupLayout({
  velA: {storage: d.arrayOf(d.vec4f, COUNT), access: 'mutable'},
  velB: {storage: d.arrayOf(d.vec4f, COUNT), access: 'mutable'},
  dyeA: {storage: d.arrayOf(d.vec4f, COUNT), access: 'mutable'},
  dyeB: {storage: d.arrayOf(d.vec4f, COUNT), access: 'mutable'},
  pressure: {storage: d.arrayOf(d.f32, COUNT), access: 'mutable'},
  divergence: {storage: d.arrayOf(d.f32, COUNT), access: 'mutable'},
  params: {uniform: FluidParams},
})
const outputLayout = tgpu.bindGroupLayout({
  dyeA: {storage: d.arrayOf(d.vec4f, COUNT), access: 'readonly'},
  outTex: {storageTexture: d.textureStorage2d('rgba16float', 'write-only')},
})

// The one pass that is this shader's own: a cone emitter at a fixed source, plus the cursor shove.
const splatKernel = buildEmitterSplatKernel(fluidLayout, {n: N, namePrefix: 'smoke', cone: true, cursorPush: true, densityGain: 8, velocityBlendGain: 3})
// Everything else is the shared solve over a density-and-age dye.
const solverKernels = buildStableFluidsKernels(fluidLayout, {n: N, namePrefix: 'smoke', boundary: 'clamped', dye: 'densityAge', dyeDissipation: true, ageAdvance: true})
const outputKernel = buildFluidOutputKernel(outputLayout, {n: N, namePrefix: 'smoke', dye: 'densityAge'})

// Smoke: fresh smoke in colorA ages toward colorB as it rises and dissipates.
export const Smoke = defineShader({
  name: 'Smoke',
  usesPointer: true,
  props: {
    colorA: {default: '#fc83f9', transform: transformColor},
    colorB: {default: '#c21c79', transform: transformColor},
    emitFrom: {default: {x: 0.5, y: 1}, transform: transformPosition},
    speed: {default: 20},
    emitRadius: {default: 0.08},
    dissipation: {default: 0.2},
    detail: {default: 25},
    mouseInfluence: {default: 0.1},
  },
  ...fluidSim(() => ({
    resolution: N,
    layout: fluidLayout, outputLayout, paramsSchema: FluidParams,
    solver: {kernels: solverKernels, jacobiIters: 10},
    output: {kernel: outputKernel, key: 'smokeTexture'},
    pointer: {minDrag: 0.0005},
    inject: [splat({kernel: splatKernel})],
    values: (f) => {
      const emit = f.getCpuValue('emitFrom') as {x: number; y: number} | undefined
      const velMag = f.num('speed', 20) * N * 0.15
      const ptr = f.ptr!
      const mouseInf = f.num('mouseInfluence', 0.1)
      const active = ptr.moving && mouseInf > 0
      const mouseRadGrid = 0.1 * N
      return {
        dt: f.dt,
        emitX: (emit?.x ?? 0.5) * N,
        emitY: (1 - (emit?.y ?? 0)) * N,
        emitVelX: 0, emitVelY: -velMag,
        perpDirX: 1, perpDirY: 0,
        spreadFactor: Math.tan(Math.PI / 6),
        emitRad: f.num('emitRadius', 0.08) * N,
        emitIntensity: 1,
        dyeFade: f.num('dissipation', 0.2),
        velFade: 0.2,
        curlStrength: f.num('detail', 25),
        gravity: 0.5,
        colorDecay: 0.4,
        cursorX: active ? ptr.x * N : 0,
        cursorY: active ? ptr.y * N : 0,
        cursorVelX: active ? ptr.dx * N * 15 * mouseInf : 0,
        cursorVelY: active ? ptr.dy * N * 15 * mouseInf : 0,
        mouseActive: active ? 1 : 0,
        mouseRadSq: mouseRadGrid * mouseRadGrid,
      }
    },
  })),
  gpu: {
    fragment: ({ctx, computeOutputs, uniforms}: GpuFragmentParams): Expr => {
      const field = computeOutputs?.smokeTexture as KitTexture | undefined
      if (!field) return ZERO // no GPU: transparent
      const s = field.sample(ctx.uv, 'linearClamp') // x = density, y = age
      const color = mixExpr(uniforms.colorA, uniforms.colorB, s.member('y'))
      return vec4(color.member('rgb'), color.member('a').mul(s.member('x')))
    },
  },
})

sim.feedback.example:
import {defineShader, sim} from 'shaders/std'
import {buildMacroblockAdvectKernel, call, mixExpr, ZERO} from '@coreroot/gpu/porters'
import type {GpuFragmentParams, KitTexture, Expr} from '@coreroot/gpu/porters'
import {blend} from '@coreroot/gpu/kit'

const {feedbackSim} = sim.feedback

const STATE_RES = 768

// The rule: each block of the picture either refreshes from the live child or holds and drags
// its previous contents along a motion vector, like a video stream that lost its keyframes.
const decoder = buildMacroblockAdvectKernel({
  res: STATE_RES,
  format: 'rgba16float',
  namePrefix: 'dataMosh',
  blockMix: {coarseScale: 2.6, coarsePick: 0.35},
  generationLoss: {levels: 18, amount: 0.12, decay: 0.9985},
})

// DataMosh: corrupted-codec smearing of the layer inside.
export const DataMosh = defineShader({
  name: 'DataMosh',
  requiresRTT: true,
  requiresChild: true,
  props: {
    intensity: {default: 0.7},
    blockSize: {default: 48},
    drift: {default: 0.35},
    churn: {default: 0.4},
    blend: {default: 1},
    speed: {default: 1},
    seed: {default: 0},
  },
  ...feedbackSim((params, root) => ({
    size: STATE_RES,
    format: 'rgba16float',
    speedProp: 'speed',
    paramsSchema: decoder.Params,
    // Hand the step the child, last frame's state, this frame's state, the display copy and the values.
    bindGroups: ({childTexture, display, paramsBuffer}, read, write) => root.createBindGroup(decoder.layout, {
      src: childTexture, prev: read.state, next: write.state, display, params: paramsBuffer,
    } as never),
    step: decoder.kernel,
    // The simulation's own clock stops with speed 0, so the smear freezes in place.
    values: ({dt, localTime}) => ({
      time: localTime,
      dt,
      seed: (params.getCpuValue('seed') as number) ?? 0,
      intensity: (params.getCpuValue('intensity') as number) ?? 0.7,
      blockSize: (params.getCpuValue('blockSize') as number) ?? 48,
      drift: (params.getCpuValue('drift') as number) ?? 0.35,
      churn: (params.getCpuValue('churn') as number) ?? 0.4,
    }),
  })),
  gpu: {
    fragment: ({childNode, ctx, computeOutputs, uniforms, convertToTexture}: GpuFragmentParams): Expr => {
      if (!childNode) return ZERO
      const display = computeOutputs?.display as KitTexture | undefined
      const childTex = (computeOutputs?.childTexture as KitTexture | undefined) ?? convertToTexture(childNode)
      const live = childTex.sample(ctx.uv)
      if (!display) return call(blend.unpremultiplyAlpha, 'unpremultiplyAlpha', [live]) // no GPU: the child untouched
      const moshed = display.sample(ctx.uv, 'linearClamp')
      return call(blend.unpremultiplyAlpha, 'unpremultiplyAlpha', [mixExpr(live, moshed, uniforms.blend)])
    },
  },
})

sim.agents.example:
import {defineShader, sim, transformColor, transformColorSpace, colorSpaceOptions} from 'shaders/std'
import {tgpu, d, agents} from '@coreroot/gpu/kit'
import {makeCpuValueGetter, readAgentFrame, resolveRenderRes, SIZE_REF_RES} from '@coreroot/gpu/porters'

const {agentSim, renderAgents, force, integrator} = sim.agents

const MAX_AGENTS = 4096
const RES = resolveRenderRes({desktop: 1024, mobile: 640})

// The values every step reads each frame, written from the props in `frame`.
const SimParams = d.struct({
  colA: d.vec4f, colB: d.vec4f,
  count: d.f32, trails: d.f32,
  dt: d.f32, aspect: d.f32, domainX: d.f32,
  maxSpeed: d.f32, maxForce: d.f32,
  perceptionSq: d.f32, sepRadiusSq: d.f32,
  sepW: d.f32, aliW: d.f32, cohW: d.f32,
  cursorX: d.f32, cursorY: d.f32, cursorMode: d.f32, cursorRadius: d.f32, cursorRadiusSq: d.f32, cursorForce: d.f32,
  bodyR: d.f32,
  margin: d.f32, turnForce: d.f32,
  seed: d.f32,
})
// Per-agent state (position + velocity), an excitement value, the two canvases, a trail canvas, the output.
const simLayout = tgpu.bindGroupLayout({
  agents: {storage: d.arrayOf(d.vec4f, MAX_AGENTS), access: 'mutable'},
  agit: {storage: d.arrayOf(d.f32, MAX_AGENTS), access: 'mutable'},
  accumE: {storage: d.arrayOf(d.atomic(d.u32), RES * RES), access: 'mutable'},
  accumS: {storage: d.arrayOf(d.atomic(d.u32), RES * RES), access: 'mutable'},
  trailBuf: {storage: d.arrayOf(d.vec4f, RES * RES), access: 'mutable'},
  params: {uniform: SimParams},
  outTex: {storageTexture: d.textureStorage2d('rgba16float', 'write-only')},
})

// Spawn already in formation, so frame one reads as a murmuration.
const boidsInit = agents.makeClusterFormationInit(simLayout, 'boidsInit')

// The physics: flocking, the cursor, and a soft turn at the edges, folded into one update step.
const boidsUpdate = integrator.steering2d(simLayout, {
  forces: [force.flocking(simLayout, {maxAgents: MAX_AGENTS}), force.cursorSteer(simLayout), force.wallTurn(simLayout)],
  agitation: {rest: 1.5, gain: 0.4545, cool: 1.3},
  cruiseFloor: 0.35,
  wallRestitution: 0.6,
  name: 'boidsUpdate',
})

// The look: comets along the heading, colored from rest to excited, into a trail canvas.
const boidsRender = (shape: string, colorSpace: number) => renderAgents.orientedWorld(simLayout, {
  shape, res: RES, splatRCap: 16, heading: 'velocity', agitation: 'buffer', comet: true,
  ramp: {colorSpace, trails: 'on'},
  names: {splat: 'boidsSplat', resolve: 'boidsResolve'},
})

// Boids: a living murmuration that flashes toward an excited color when the cursor scatters it.
export const Boids = defineShader({
  name: 'Boids',
  usesPointer: true,
  props: {
    colorA: {default: '#8ec5ff', transform: transformColor},
    colorB: {default: '#ff7ad9', transform: transformColor},
    colorSpace: {default: 'oklab', transform: transformColorSpace, compileTime: true, ui: {type: 'select', options: colorSpaceOptions}},
    agentShape: {default: 'arrow', compileTime: true, ui: {type: 'select', options: agents.orientedShapeOptions}},
    count: {default: 2000},
    speed: {default: 2},
    seed: {default: 0},
    size: {default: 1.5},
    trails: {default: 0},
    perception: {default: 0.12},
    cursorStrength: {default: 1.5},
  },
  ...agentSim<typeof SimParams>({
    layout: simLayout,
    params: SimParams,
    maxAgents: MAX_AGENTS,
    countCap: {desktop: MAX_AGENTS, mobile: 1200},
    output: {key: 'outTex', name: 'boidsTexture', size: [RES, RES], format: 'rgba16float'},
    bake: ({getCpuValue}) => {
      const render = boidsRender((getCpuValue('agentShape') as string) || 'arrow', (getCpuValue('colorSpace') as number) ?? 2)
      return {
        pipelines: {
          init: {kernel: boidsInit, threads: 'max'},
          update: {kernel: boidsUpdate, threads: 'agents'},
          splat: render.splat,
          resolve: render.resolve,
        },
        initStep: 'init',
        program: ['update', 'splat', 'resolve'],
      }
    },
    frame: (sys, {getCpuValue}) => {
      const g = makeCpuValueGetter(getCpuValue)
      return (frameParams) => {
        const {dt, aspect, pointerX, pointerY} = readAgentFrame(frameParams)
        const count = sys.resolveCount(g('count', 2000))
        const maxSpeed = 0.13 * g('speed', 2)
        const perception = g('perception', 0.12)
        const colA = getCpuValue('colorA') as {x: number; y: number; z: number; w: number} | undefined
        const colB = getCpuValue('colorB') as {x: number; y: number; z: number; w: number} | undefined
        sys.writeParams({
          colA: d.vec4f(colA?.x ?? 0.56, colA?.y ?? 0.77, colA?.z ?? 1, colA?.w ?? 1),
          colB: d.vec4f(colB?.x ?? 1, colB?.y ?? 0.48, colB?.z ?? 0.85, colB?.w ?? 1),
          count, trails: Math.min(Math.max(g('trails', 0), 0), 1) * 0.92,
          dt, aspect, domainX: Math.max(aspect, 0.01),
          maxSpeed, maxForce: maxSpeed * 3.5,
          perceptionSq: perception * perception,
          sepRadiusSq: (perception * 0.5) * (perception * 0.5),
          sepW: 1.7, aliW: 1.5, cohW: 1,
          cursorX: pointerX * aspect, cursorY: pointerY, cursorMode: 2,
          cursorRadius: 0.22, cursorRadiusSq: 0.22 * 0.22,
          cursorForce: g('cursorStrength', 1.5) * maxSpeed * 12,
          bodyR: Math.min(Math.max(g('size', 1.5), 0.5), 3) * 2 / SIZE_REF_RES,
          margin: 0.07, turnForce: maxSpeed * 2.2,
          seed: g('seed', 0),
        })
        return sys.frame({count, reseed: g('seed', 0)})
      }
    },
    fragment: {output: 'boidsTexture', fallback: 'transparent'},
  }),
})

sim.agentForces.example:
import {defineShader, sim, transformColor} from 'shaders/std'
import {tgpu, d, agents} from '@coreroot/gpu/kit'
import {makeCpuValueGetter, readAgentFrame, resolveRenderRes, SIZE_REF_RES} from '@coreroot/gpu/porters'

const {agentSim, renderAgents, torque, field, integrator, agentFrame} = sim.agents

const MAX_FILINGS = 12288
const RES = resolveRenderRes({desktop: 1024, mobile: 768})
const OVERSCAN = 0.14

// The values the torques, the field and the home read each frame.
const SimParams = d.struct({
  colA: d.vec4f, colB: d.vec4f,
  count: d.f32,
  dt: d.f32, aspect: d.f32, domainX: d.f32,
  cursorX: d.f32, cursorY: d.f32, axisX: d.f32, axisY: d.f32,
  fieldType: d.f32, restMode: d.f32,
  strength: d.f32, reachSq: d.f32,
  alignK: d.f32, damping: d.f32, restK: d.f32, pullK: d.f32, homeK: d.f32,
  omegaRef: d.f32, agitCool: d.f32,
  gridCols: d.f32, cellW: d.f32, cellH: d.f32, jitter: d.f32,
  bodyR: d.f32,
})
// Per-agent state (offset from home, angle, spin), excitement, the two canvases, the output.
const simLayout = tgpu.bindGroupLayout({
  agents: {storage: d.arrayOf(d.vec4f, MAX_FILINGS), access: 'mutable'},
  agit: {storage: d.arrayOf(d.f32, MAX_FILINGS), access: 'mutable'},
  accumE: {storage: d.arrayOf(d.atomic(d.u32), RES * RES), access: 'mutable'},
  accumS: {storage: d.arrayOf(d.atomic(d.u32), RES * RES), access: 'mutable'},
  params: {uniform: SimParams},
  outTex: {storageTexture: d.textureStorage2d('rgba16float', 'write-only')},
})

const filingsInit = agents.makeRestingDirectorInit(simLayout, 'filingsInit')

// The physics: every filing rests on a jittered grid, samples the magnet at the cursor, and
// swings onto its field line, with a weak pull back to its rest angle where the field is faint.
const filingsHome = field.jitteredGridHome(simLayout, {overscan: OVERSCAN})
const filingsUpdate = integrator.orientation2d(simLayout, {
  home: filingsHome,
  fieldAt: field.dipoleOrRadial(simLayout),
  torques: [torque.alignToField(simLayout), torque.rest(simLayout)],
  maxOffset: 0.12,
  name: 'filingsUpdate',
})

// The look: slivers drawn along each filing's own angle, colored calm to excited.
const filingsRender = renderAgents.orientedWorld(simLayout, {
  shape: 'streak', res: RES, splatRCap: 14, heading: 'angle', agitation: 'buffer', comet: false, home: filingsHome,
  ramp: {colorSpace: 2, trails: 'none'},
  names: {splat: 'filingsSplat', resolve: 'filingsResolve'},
})

// MagneticFilings: iron filings that reveal the field lines of a magnet at the cursor.
export const MagneticFilings = defineShader({
  name: 'MagneticFilings',
  usesPointer: true,
  props: {
    colorA: {default: '#85929e', transform: transformColor},
    colorB: {default: '#ff9d5c', transform: transformColor},
    count: {default: 5000},
    strength: {default: 1},
    reach: {default: 0.35},
    response: {default: 0.5},
    size: {default: 1},
  },
  ...agentSim<typeof SimParams>({
    layout: simLayout,
    params: SimParams,
    maxAgents: MAX_FILINGS,
    output: {key: 'outTex', name: 'filingsTexture', size: [RES, RES], format: 'rgba16float'},
    bake: () => ({
      pipelines: {
        init: {kernel: filingsInit, threads: 'max'},
        update: {kernel: filingsUpdate, threads: 'agents'},
        splat: filingsRender.splat,
        resolve: filingsRender.resolve,
      },
      initStep: 'init',
      program: ['update', 'splat', 'resolve'],
    }),
    frame: (sys, {getCpuValue}) => {
      const g = makeCpuValueGetter(getCpuValue)
      // The magnet's axis follows where the cursor has been travelling.
      const motionAxis = agentFrame.createMotionAxis({smoothing: 0.1, teleport: 0.25})
      return (frameParams) => {
        const {dt, aspect, pointerX, pointerY} = readAgentFrame(frameParams)
        const domainX = Math.max(aspect, 0.01)
        const count = sys.resolveCount(g('count', 5000))
        const {cols, cellW, cellH} = agentFrame.fitJitteredGrid(count, domainX, OVERSCAN)
        const cursorX = pointerX * aspect
        const cursorY = pointerY
        const axis = motionAxis.update(cursorX, cursorY)
        const reach = g('reach', 0.35)
        const colA = getCpuValue('colorA') as {x: number; y: number; z: number; w: number} | undefined
        const colB = getCpuValue('colorB') as {x: number; y: number; z: number; w: number} | undefined
        sys.writeParams({
          colA: d.vec4f(colA?.x ?? 0.52, colA?.y ?? 0.57, colA?.z ?? 0.64, colA?.w ?? 1),
          colB: d.vec4f(colB?.x ?? 1, colB?.y ?? 0.62, colB?.z ?? 0.36, colB?.w ?? 1),
          count,
          dt, aspect, domainX,
          cursorX, cursorY, axisX: axis.x, axisY: axis.y,
          fieldType: 0, restMode: 0,
          strength: g('strength', 1), reachSq: reach * reach,
          alignK: 45, damping: 3 + Math.min(Math.max(g('response', 0.5), 0), 1) * 9,
          restK: 6, pullK: 0.25, homeK: 2.5,
          omegaRef: 6, agitCool: 1,
          gridCols: cols, cellW, cellH, jitter: 0.85,
          bodyR: Math.min(Math.max(g('size', 1), 0.5), 3) * 1.7 / SIZE_REF_RES,
        })
        return sys.frame({count})
      }
    },
    fragment: {output: 'filingsTexture', fallback: 'transparent'},
  }),
})

sim.agentFrame.example:
import {defineShader, sim, transformColor} from 'shaders/std'
import {tgpu, d, agents} from '@coreroot/gpu/kit'
import {makeCpuValueGetter, readAgentFrame, resolveRenderRes, SIZE_REF_RES} from '@coreroot/gpu/porters'

const {agentSim, renderAgents, force, drift, integrator, agentFrame, pointSlot} = sim.agents

const MAX_MOTES = 8192
const RES = resolveRenderRes({desktop: 1024, mobile: 512})
const DEG_TO_RAD = Math.PI / 180

const SimParams = d.struct({
  color: d.vec4f,
  count: d.f32, dt: d.f32, time: d.f32, aspect: d.f32, domainX: d.f32,
  driftBase: d.f32, angleRad: d.f32, speedVar: d.f32, angleVarRad: d.f32,
  randomness: d.f32, twinkle: d.f32, softness: d.f32,
  bodyR: d.f32,
  cursorX: d.f32, cursorY: d.f32, cursorRadSq: d.f32, cursorForce: d.f32, dragMul: d.f32,
})
const simLayout = tgpu.bindGroupLayout({
  agents: {storage: d.arrayOf(d.vec4f, MAX_MOTES), access: 'mutable'},
  accumE: {storage: d.arrayOf(d.atomic(d.u32), RES * RES), access: 'mutable'},
  params: {uniform: SimParams},
  outTex: {storageTexture: d.textureStorage2d('rgba16float', 'write-only')},
})

const motesInit = agents.makeUniformScatterInit(simLayout, 'motesInit')
const motesUpdate = integrator.drift2d(simLayout, {drift: drift.variedHeading(simLayout), gust: force.cursorGust(simLayout), name: 'motesUpdate'})
const motesRender = renderAgents.pointWorld(simLayout, {
  shape: 'dot', res: RES,
  place: pointSlot.orbitalPlace(simLayout, {radius: 0.035, rate: 1.4}),
  brightness: pointSlot.twinkleBrightness(simLayout, {freq: 2}),
  bodyRadius: pointSlot.presenceRadius(simLayout),
  names: {splat: 'motesSplat', resolve: 'motesResolve'},
})

// Motes: drifting particles the cursor can stir. The frame turns props into the values the steps
// read; the gust's fade is a rate per second, made frame-rate independent by expDecay.
export const Motes = defineShader({
  name: 'Motes',
  usesPointer: true,
  props: {
    particleColor: {default: '#ffffff', transform: transformColor},
    count: {default: 1200},
    speed: {default: 0.25},
    angle: {default: 90},
    particleSize: {default: 1.2},
    cursorStrength: {default: 0.5},
  },
  ...agentSim<typeof SimParams>({
    layout: simLayout,
    params: SimParams,
    maxAgents: MAX_MOTES,
    countCap: {desktop: MAX_MOTES, mobile: 3000},
    output: {key: 'outTex', name: 'particleTexture', size: [RES, RES], format: 'rgba16float'},
    bake: () => ({
      pipelines: {
        init: {kernel: motesInit, threads: 'max'},
        update: {kernel: motesUpdate, threads: 'agents'},
        splat: motesRender.splat,
        resolve: motesRender.resolve,
      },
      initStep: 'init',
      program: ['update', 'splat', 'resolve'],
    }),
    frame: (sys, {getCpuValue}) => {
      const g = makeCpuValueGetter(getCpuValue)
      let localTime = 0
      return (frameParams) => {
        const {dt, aspect, pointerX, pointerY} = readAgentFrame(frameParams)
        localTime += dt
        const count = sys.resolveCount(g('count', 1200))
        const col = getCpuValue('particleColor') as {x: number; y: number; z: number; w: number} | undefined
        sys.writeParams({
          color: d.vec4f(col?.x ?? 1, col?.y ?? 1, col?.z ?? 1, col?.w ?? 1),
          count, dt, time: localTime, aspect, domainX: Math.max(aspect, 0.01),
          driftBase: Math.min(Math.max(g('speed', 0.25), 0), 1.5) * 0.48,
          angleRad: g('angle', 90) * DEG_TO_RAD + Math.PI,
          speedVar: 0.3,
          angleVarRad: 30 * DEG_TO_RAD,
          randomness: 0.25,
          twinkle: 0.5,
          softness: 0.1,
          bodyR: Math.min(Math.max(g('particleSize', 1.2), 0.3), 4) * 2 / SIZE_REF_RES,
          cursorX: pointerX * aspect, cursorY: pointerY,
          cursorRadSq: 0.22 * 0.22,
          cursorForce: Math.min(Math.max(g('cursorStrength', 0.5), 0), 1) * 3.5,
          // The gust fades at 1.1 per second, whatever the frame rate.
          dragMul: agentFrame.expDecay(1.1, dt),
        })
        return sys.frame({count})
      }
    },
    fragment: {output: 'particleTexture', fallback: 'transparent'},
  }),
})

sim.agentRender.example:
import {defineShader, sim, transformColor} from 'shaders/std'
import {tgpu, d, agents} from '@coreroot/gpu/kit'
import {makeCpuValueGetter, readAgentFrame, resolveRenderRes, SIZE_REF_RES} from '@coreroot/gpu/porters'

const {agentSim, force, drift, integrator, agentFrame} = sim.agents
const {splat, resolve, pointSlot} = sim.agentRender

const MAX_MOTES = 8192
const RES = resolveRenderRes({desktop: 1024, mobile: 512})

const SimParams = d.struct({
  color: d.vec4f,
  count: d.f32, dt: d.f32, time: d.f32, aspect: d.f32, domainX: d.f32,
  driftBase: d.f32, angleRad: d.f32, speedVar: d.f32, angleVarRad: d.f32,
  randomness: d.f32, twinkle: d.f32, softness: d.f32,
  bodyR: d.f32,
  cursorX: d.f32, cursorY: d.f32, cursorRadSq: d.f32, cursorForce: d.f32, dragMul: d.f32,
})
const simLayout = tgpu.bindGroupLayout({
  agents: {storage: d.arrayOf(d.vec4f, MAX_MOTES), access: 'mutable'},
  accumE: {storage: d.arrayOf(d.atomic(d.u32), RES * RES), access: 'mutable'},
  params: {uniform: SimParams},
  outTex: {storageTexture: d.textureStorage2d('rgba16float', 'write-only')},
})

const motesInit = agents.makeUniformScatterInit(simLayout, 'motesInit')
const motesUpdate = integrator.drift2d(simLayout, {drift: drift.variedHeading(simLayout), gust: force.cursorGust(simLayout), name: 'motesUpdate'})

// The look, paired by hand: a point splat whose placement, brightness and size are pointSlot
// parts, closed by the tint resolve over the same canvas.
const motesSplat = splat.pointWorld(simLayout, {
  shape: 'glow', res: RES,
  place: pointSlot.orbitalPlace(simLayout, {radius: 0.035, rate: 1.4}),
  brightness: pointSlot.twinkleBrightness(simLayout, {freq: 2}),
  bodyRadius: pointSlot.presenceRadius(simLayout),
  name: 'motesSplat',
})
const motesResolve = resolve.tint(simLayout, {res: RES, name: 'motesResolve'})

// Motes: soft drifting points that twinkle and circle lazily around their path.
export const Motes = defineShader({
  name: 'Motes',
  usesPointer: true,
  props: {
    particleColor: {default: '#ffffff', transform: transformColor},
    count: {default: 1200},
    speed: {default: 0.25},
    randomness: {default: 0.25},
    twinkle: {default: 0.5},
    softness: {default: 0.1},
    particleSize: {default: 1.2},
  },
  ...agentSim<typeof SimParams>({
    layout: simLayout,
    params: SimParams,
    maxAgents: MAX_MOTES,
    countCap: {desktop: MAX_MOTES, mobile: 3000},
    output: {key: 'outTex', name: 'particleTexture', size: [RES, RES], format: 'rgba16float'},
    bake: () => ({
      pipelines: {
        init: {kernel: motesInit, threads: 'max'},
        update: {kernel: motesUpdate, threads: 'agents'},
        splat: {kernel: motesSplat, threads: 'agents'},
        resolve: {kernel: motesResolve, threads: 'fixed', size: [RES, RES]},
      },
      initStep: 'init',
      program: ['update', 'splat', 'resolve'],
    }),
    frame: (sys, {getCpuValue}) => {
      const g = makeCpuValueGetter(getCpuValue)
      let localTime = 0
      return (frameParams) => {
        const {dt, aspect, pointerX, pointerY} = readAgentFrame(frameParams)
        localTime += dt
        const count = sys.resolveCount(g('count', 1200))
        const col = getCpuValue('particleColor') as {x: number; y: number; z: number; w: number} | undefined
        sys.writeParams({
          color: d.vec4f(col?.x ?? 1, col?.y ?? 1, col?.z ?? 1, col?.w ?? 1),
          count, dt, time: localTime, aspect, domainX: Math.max(aspect, 0.01),
          driftBase: Math.min(Math.max(g('speed', 0.25), 0), 1.5) * 0.48,
          angleRad: Math.PI * 1.5,
          speedVar: 0.3,
          angleVarRad: Math.PI / 6,
          randomness: Math.min(Math.max(g('randomness', 0.25), 0), 1),
          twinkle: Math.min(Math.max(g('twinkle', 0.5), 0), 1),
          softness: Math.min(Math.max(g('softness', 0.1), 0), 1),
          bodyR: Math.min(Math.max(g('particleSize', 1.2), 0.3), 4) * 2 / SIZE_REF_RES,
          cursorX: pointerX * aspect, cursorY: pointerY,
          cursorRadSq: 0.22 * 0.22,
          cursorForce: 0,
          dragMul: agentFrame.expDecay(1.1, dt),
        })
        return sys.frame({count})
      }
    },
    fragment: {output: 'particleTexture', fallback: 'transparent'},
  }),
})

sim.shapeFields.example:
import {defineShader, sim, transformColor} from 'shaders/std'
import {tgpu, d, sdf, agents} from '@coreroot/gpu/kit'
import {makeCpuValueGetter, readAgentFrame, resolveRenderRes, SIZE_REF_RES} from '@coreroot/gpu/porters'

const {agentSim, renderAgents, force, integrator, agentFrame, shapeField} = sim.agents

const MAX_PARTICLES = 16000
const DGRID = 32
const DOMAIN = 1.0
const OUT_RES = resolveRenderRes({desktop: 1024, mobile: 768})
const MAX_SPEED = 3

const SimParams = d.struct({
  colA: d.vec4f, colB: d.vec4f,
  dt: d.f32, time: d.f32, spread: d.f32, agitation: d.f32,
  dragMul: d.f32, gravX: d.f32, gravY: d.f32, halfDepth: d.f32,
  cursorX: d.f32, cursorY: d.f32, cursorForce: d.f32, cursorRadSq: d.f32,
  saRadius: d.f32, saSides: d.f32, saRounding: d.f32, saInnerRatio: d.f32,
  saRotation: d.f32, saHeight: d.f32, saOffset: d.f32, saAperture: d.f32,
  centerX: d.f32, centerYv: d.f32, scale: d.f32, rotC: d.f32, rotS: d.f32, aspect: d.f32,
  size: d.f32, exposure: d.f32, softness: d.f32, speedColorK: d.f32,
  omegaX: d.f32, omegaY: d.f32, omegaZ: d.f32, entrain: d.f32,
  gridOffX: d.f32, gridOffY: d.f32, gridOffZ: d.f32,
})
const simLayout = tgpu.bindGroupLayout({
  pos: {storage: d.arrayOf(d.vec4f, MAX_PARTICLES), access: 'mutable'},
  vel: {storage: d.arrayOf(d.vec4f, MAX_PARTICLES), access: 'mutable'},
  dens: {storage: d.arrayOf(d.atomic(d.u32), DGRID * DGRID * DGRID), access: 'mutable'},
  accumE: {storage: d.arrayOf(d.atomic(d.u32), OUT_RES * OUT_RES), access: 'mutable'},
  accumS: {storage: d.arrayOf(d.atomic(d.u32), OUT_RES * OUT_RES), access: 'mutable'},
  params: {uniform: SimParams},
  outTex: {storageTexture: d.textureStorage2d('rgba16float', 'write-only')},
})

const swarmInit = agents.makeBallCloudInit(simLayout, 'swarmInit')
// Even filling: particles are counted into a density grid and slide away from crowding.
const pressure = force.pressure(simLayout, {gridDim: DGRID, domain: DOMAIN, names: {clear: 'swarmClearDensity', splat: 'swarmDensity'}})

// A hexagon with depth, as the field the containment force reads. Its radius, sides and rounding
// arrive through the values struct each frame.
const hexField = shapeField.analyticExtruded(simLayout, sdf.buildAnalyticSdfFn('polygonSDF'))
const swarmUpdate = integrator.forces3d(simLayout, {
  forces: [
    pressure.force,
    force.containment(simLayout, {
      field: hexField,
      gradEps: 0.02,
      wall: {featherFrom: -0.10, featherTo: 0.01, base: 1.1, springK: 22},
      recall: {from: DOMAIN * 0.85, to: DOMAIN * 1.1, k: 9},
      homing: {from: 0.12, to: 0.45, k: 5},
      entrainment: {featherHalf: 0.05},
    }),
    force.cursorXY(simLayout),
    force.gravity(simLayout),
    force.turbulence(simLayout, {posScale: 193, timeX: 31.7, timeY: 27.3, seedScale: 997, gain: 5}),
  ],
  maxSpeed: MAX_SPEED,
  posClamp: 1.9,
  name: 'swarmUpdate',
})
const swarmRender = renderAgents.volume(simLayout, {
  shape: 'dot', outRes: OUT_RES, maxSplatSize: 6, extQ: 2.6,
  ramp: {colorSpace: 0, exposure: true, trails: 'none'},
  names: {splat: 'swarmSplat', glow: 'swarmGlowProfile', profile: 'swarmProfile', resolve: 'swarmResolve'},
})

// HexSwarm: particles that fill a hexagon evenly and scatter when the cursor pushes through them.
export const HexSwarm = defineShader({
  name: 'HexSwarm',
  usesPointer: true,
  props: {
    colorA: {default: '#ffffff', transform: transformColor},
    colorB: {default: '#ff7ad9', transform: transformColor},
    count: {default: 4000},
    radius: {default: 0.35},
    depth: {default: 0.18},
    spread: {default: 1},
    damping: {default: 0.4},
    mouseInfluence: {default: 1.2},
  },
  ...agentSim<typeof SimParams>({
    layout: simLayout,
    params: SimParams,
    maxAgents: MAX_PARTICLES,
    countCap: {desktop: MAX_PARTICLES, mobile: 6000},
    output: {key: 'outTex', name: 'particleTexture', size: [OUT_RES, OUT_RES], format: 'rgba16float'},
    bake: () => ({
      pipelines: {
        init: {kernel: swarmInit, threads: 'max'},
        clearDensity: {kernel: pressure.clearKernel, threads: 'fixed', size: [pressure.cells]},
        density: {kernel: pressure.splatKernel, threads: 'agents'},
        update: {kernel: swarmUpdate, threads: 'agents'},
        splat: swarmRender.splat,
        resolve: swarmRender.resolve,
      },
      initStep: 'init',
      program: ['clearDensity', 'density', 'update', 'splat', 'resolve'],
    }),
    frame: (sys, {getCpuValue}) => {
      const g = makeCpuValueGetter(getCpuValue)
      let time = 0
      let frameIdx = 0
      const CELL = (2 * DOMAIN) / DGRID
      return (frameParams) => {
        const {dt, aspect, pointerX, pointerY} = readAgentFrame(frameParams, 1)
        time += dt
        const centerX = 0.5, centerYv = 0.5, scale = 1, rotC = 1, rotS = 0
        // The pointer in the shape's own coordinates, so the cursor force acts where the swarm lives.
        const cursor = agentFrame.pointerToShapeLocal({pointerX, pointerY, centerX, centerYv, scale, rotC, rotS, aspect})
        const gridOff = agentFrame.r3SubCellOffset(frameIdx++, CELL)
        const colA = getCpuValue('colorA') as {x: number; y: number; z: number; w: number} | undefined
        const colB = getCpuValue('colorB') as {x: number; y: number; z: number; w: number} | undefined
        sys.writeParams({
          colA: d.vec4f(colA?.x ?? 1, colA?.y ?? 1, colA?.z ?? 1, colA?.w ?? 1),
          colB: d.vec4f(colB?.x ?? 1, colB?.y ?? 0.48, colB?.z ?? 0.85, colB?.w ?? 1),
          dt, time,
          spread: g('spread', 1),
          agitation: 0.12,
          dragMul: agentFrame.expDecay(2.2 + g('damping', 0.4) * 6, dt),
          gravX: 0, gravY: 0,
          halfDepth: Math.max(g('depth', 0.18), 0.01) * 0.5,
          cursorX: cursor.x, cursorY: cursor.y,
          cursorForce: g('mouseInfluence', 1.2) * 3,
          cursorRadSq: 0.22 * 0.22,
          saRadius: g('radius', 0.35), saSides: 6, saRounding: 0, saInnerRatio: 0.4,
          saRotation: 0, saHeight: 0.25, saOffset: 0.2, saAperture: 270,
          centerX, centerYv, scale, rotC, rotS, aspect,
          size: 2.2 * OUT_RES / SIZE_REF_RES,
          exposure: 1,
          softness: 0.5,
          speedColorK: 2 / MAX_SPEED,
          omegaX: 0, omegaY: 0, omegaZ: 0, entrain: 0,
          gridOffX: gridOff.x, gridOffY: gridOff.y, gridOffZ: gridOff.z,
        })
        return sys.frame({count: sys.resolveCount(g('count', 4000))})
      }
    },
    fragment: {output: 'particleTexture', fallback: 'transparent'},
  }),
})

