import {defineShader, wgsl, transformColor, transformPosition} from 'shaders/std'

export const Halo = defineShader({
  name: 'Halo',
  animatedTime: {speed: 'speed'},
  props: {
    inner: {default: '#ffd166', transform: transformColor},
    outer: {default: '#0b132b', transform: transformColor},
    center: {default: {x: 0.5, y: 0.5}, transform: transformPosition},
    radius: {default: 0.6},
    bands: {default: 4},
    speed: {default: 1},
  },
  paint: wgsl`
    let d = length((uv - center) * vec2f(aspect, 1.0)) / radius;
    let wave = 0.5 + 0.5 * cos(d * bands * 6.2831853 - time * 2.0);
    return vec4f(mix(outer.rgb, inner.rgb, wave * (1.0 - smoothstep(0.7, 1.0, d))), 1.0);
  `,
})

// A filter composed from std words, skipped entirely while `intensity` is 0.
export const Vignette = defineShader({
  name: 'Vignette',
  props: {
    color: {default: '#000000', transform: transformColor},
    center: {default: {x: 0.5, y: 0.5}, transform: transformPosition},
    radius: {default: 0.5},
    falloff: {default: 0.5},
    intensity: {default: 1, recompile: crosses(0)},
  },
  effect: tintToward(p('color'), {amount: radialMask({center: p('center'), radius: p('radius'), falloff: p('falloff')}).times(p('intensity'))}),
  identityWhen: isZero('intensity'),
})

paint: wgsl`
  let d = length((uv - center) * vec2f(aspect, 1.0)) / radius;
  return vec4f(mix(outer.rgb, inner.rgb, 1.0 - smoothstep(0.0, 1.0, d)), 1.0);
`

// A gather filter: the layer inside, sampled at a rippled coordinate.
effect: wgsl`
  let wave = sin(length(uv - center) * frequency - time * 4.0) * amplitude;
  return textureSample(childTexture, childSampler, uv + wave);
`

paint: (params) => {
  const {uv} = paintFrame(params)
  const center = uniformOf(p('center'), params)
  const d = length(sub(uv, vec2(center.member('x'), sub(1, center.member('y')))))
  return vec4(splat3(smoothstep(0, 0.5, d)), 1)
}

paint: (params) => {
  const color = uniformOf(p('color'), params)
  const gain = mul(uniformOf(p('intensity'), params), 0.5)
  return vec4(mul(color.member('rgb'), gain), color.member('a'))
}

export function saturate(intensity: ArgSpec): PointwiseEffect {
  return pointwiseOp(colorOps.saturate, 'saturate', [intensity])
}

const lights = listOf(params, 'lights')
const rgb = accumulate(lights, (i) => {
  const light = lights.at(i)
  const pos = light.position('position')
  const d = length(sub(uv, vec2(pos.member('x'), sub(1, pos.member('y')))))
  return mul(light.color('color').member('rgb'), div(light.number('intensity'), add(1, mul(d, d))))
}, {zero: 'vec3f', deps: [uv], hint: 'lightSum'})

