    /** The field at this pixel, and one step right and one step down when the stencil took them. */
    s0: Expr
    sX?: Expr
    sY?: Expr
    /** Signed distance to the shape's edge: negative inside, zero on the edge. */
    sdf: Expr
    /** One pixel, as a fraction of the canvas height. */
    pxH: Expr
    /** Canvas width divided by height. */
    aspect: Expr
}

volume.InteriorRay.text:
interface InteriorRay {
    /** The depth at which the ray enters the shape. 0 for flat shapes. */
    entry: Expr
    /** How far the ray travels inside the shape, roughly 0–1. */
    length: Expr
    /** The position inside the shape at depth `z` along the ray. */
    at(z: Expr): {x: Expr; y: Expr}
}

volume.VolumeMarchStep.text:
