    /** The step number, 0 first. A plain number, handy for naming per-step values. */
    i: number
    /** How far along the ray this step sits, 0–1. A plain number. */
    t: number
    /** The depth of this sample along the ray, to pass to `ray.at`. */
    z: Expr
}

radiance.GatherSpec.text:
interface GatherSpec {
    /** The pixel, as a 2D point in the shape field's coordinates. */
    origin: Expr
    /** The shape as a signed distance: given a point, how far it is from the edge (negative inside). */
    field: (at: Expr) => Expr
    /** How many directions to look in. 16 is nearly noise-free. Fixed when the shader compiles. */
    cones: number
    /** The most steps each direction may take toward the shape. */
    steps: number
    /** The distance beyond which light no longer counts, in field units. */
    reach: Expr | number
    /** Where each direction starts looking. The pixel's own distance to the shape is the natural start. */
    start: Expr | number
    /** How close counts as touching the edge, about one device pixel in field units. */
    surfaceEps: Expr | number
    /** A per-pixel 0–1 value that turns the fan of directions so its structure becomes fine grain. */
    jitter: Expr | number
    /** How bright the edge is where a direction touches it, as a single number. */
    emission: (hit: {point: Expr; normal: Expr; distance: Expr; coverage: Expr}) => Expr
    /** Values from outside that `emission` also uses. List them here or they are out of scope. */
    deps?: Expr[]
    hint?: string
}

radiance.ShadowSpec.text:
interface ShadowSpec {
    /** The point being lit, moved a couple of pixels off the shape's edge along its normal. */
    from: Expr
    /** Where the light is, in the same coordinates. */
    toward: Expr
    /** The shape as a signed distance: given a point, how far it is from the edge (negative inside). */
    field: (at: Expr) => Expr
    /** The most steps the ray may take. 12 is typical. */
    steps: number
    /** How close counts as hitting the shape, about one device pixel in field units. */
    surfaceEps: Expr | number
    /** How wide the soft edge of the shadow is, 0–1. 0 is a hard shadow. */
    softness?: Expr | number
    hint?: string
}

radiance.IrradianceFieldSpec.text:
interface IrradianceFieldSpec {
    /**
     * How many rays each texel casts per frame: `burst` on the first frame after something
     * changes, `motion` while changes keep coming, then `refine` for each of `refineFrames`
     * frames once the scene is still. After that nothing runs until the next change.
     */
    rays: {burst: number; motion: number; refine: number; refineFrames: number}
    /** The most steps a ray may take toward the shape (default 32). */
    steps?: number
    /** The most steps a shadow ray may take. 0 turns shadows off entirely (default 12). */
    shadowSteps?: number
    /** The size of the square light texture, in texels per side. 512 is plenty; it is a smooth field. */
    resolution: number
    /**
     * Your list prop of lights (made with `listPropConfig`) and the names of its item fields: a
     * `position`, a `color` and a `number` for intensity. A light's position may be driven by the mouse.
     */
    lights: {prop: string; position: string; color: string; intensity: string}
    /** The prop holding how far from the shape light is gathered, relative to the shape. */
    reach: string
    /** The prop holding how far light wraps around edges facing away from it, 0–1. */
    wrap: string
    /** The prop holding each light's range: the distance at which it falls to half strength. */
    lightRange: string
    /** The prop holding the shadow's soft-edge width, 0–1. */
    shadowSoftness: string
    /** The name the texture is published under for other compute passes (default 'irradianceTexture'). */
    outputKey?: string
    namePrefix?: string
}

voxels.VoxelSurfaceSpec.text:
interface VoxelSurfaceSpec {
    /** The block style, `'cube' | 'sphere' | 'rounded'`. Mark the prop `compileTime: true`. */
    style: PropRef
    /** Where the grid sits, `'shape' | 'view'`. Mark the prop `compileTime: true`. */
    gridSpace: PropRef
    /** The edge length of one block, relative to the shape. 0.035 is about a tenth of the default sphere. */
    voxelSize: PropRef
    /** How eagerly cells along the surface fill in, −0.5 to 0.5. Negative carves the model thinner, positive puffs it out. */
    fill: PropRef
    /** The size of each block inside its cell, 0.3–1. 1 touches its neighbours, less opens gaps. */
    voxelScale: PropRef
    /** Corner rounding as a fraction of the block size, 0–1. A hairline chamfer on cubes, the corner radius of rounded cubes. */
    bevel: PropRef
    /** The soft-edge width of cast shadows, 0–1. 0 is razor sharp. */
    shadowSoftness: PropRef
    /** Optional camera tilt, in degrees. */
    pitch?: PropRef
    /** Optional camera turn, in degrees. */
    yaw?: PropRef
    /** Optional turntable speed. Declare `animatedTime: {speed: 'spin'}` too. A speed of 1 is one turn every ten seconds. */
    spin?: PropRef
    /** The direction the key light comes from, in degrees around the canvas. Shadows fall away from it. */
    lightAngle: PropRef
    /** How high the key light sits above the canvas, in degrees. Low for long shadows, high for flat top light. */
    lightElevation: PropRef
    /** The thickness given to flat shapes so they become a slab of blocks, relative to the shape. 3D shapes ignore it. */
    depth: PropRef
    /** Your material: the color of one block. Return `vec4(rgb, vox.coverage)`. */
    surface: (vox: VoxelFrame, frame: SurfaceFrame, params: GpuFragmentParams) => Expr
}

voxels.VoxelFrame.text:
interface VoxelFrame {
    /** The shape field basics: `sdf`, `pxH` (one pixel in uv) and `aspect`. */
    field: SurfaceField
    /** 1 when this is a real block, 0 for an empty slot. Return it as your alpha. */
    coverage: Expr
    /** The block's unit normal at this pixel. x right, y down, z negative toward the viewer. */
    normal: Expr
    /** How open the block's surroundings are, 1 in the open and lower in creases. Multiply ambient light by it. */
    ao: Expr
    /** How much shadow other blocks cast here, 0 in the light and 1 fully shadowed. */
    shadow: Expr
    /** The block's grid position as three whole numbers in a vec3. */
    cell: Expr
    /** A random 0–1 number that stays the same for this block every frame. Use it for per-block color variation. */
    cellHash: Expr
    /** How high the block sits, 0 at the bottom of the model and 1 at the top. */
    heightT: Expr
    /** How deep the block sits, 0 nearest the viewer and 1 farthest. */
    depthT: Expr
    /** How far this pixel is from the centre of its face toward the edge, 0–1. Seams live near 1. */
    edge: Expr
    /** The view ray into the scene, in the same convention as `normal`. */
    view: Expr
    /** The block style in force, known when the shader compiles. */
    style: VoxelStyle
}

