    derive: Record<string, GridDeriveOp>
    /** Let the engine stop running the simulation once the field has faded to nothing. */
    // 'derived-from-damping': the settle window is computed from the damping value each frame
    // (see `createWaveFieldSim`); low damping keeps the sim running, high damping sleeps fast.
    rest?: {settlesWhen: 'derived-from-damping'}
}

simulate.SimOutputRef.text:
interface SimOutputRef {
    readonly kind: 'simOutput'
    readonly sim: GridSim
    readonly output: string
}

sim.grids.GridFrameParams.text:
interface GridFrameParams {
    pointer?: {x: number; y: number}
    deltaTime?: number
    dimensions?: {width: number; height: number}
}

sim.grids.GridFrame.text:
interface GridFrame {
    /** Seconds since the last frame, never more than `clampDt`. */
    dt: number
    /** Wall-clock milliseconds this frame. */
    // `Date.now()` — the settle gates' clock.
    now: number
    /** A numeric prop's current value, or `fallback` when it is not a number this frame. */
    num(key: string, fallback: number): number
    /** Any prop's current value. */
    getCpuValue(key: string): unknown
    frameParams: GridFrameParams
}

sim.grids.GridStage.text:
interface GridStage {
    /** Return false to run nothing this frame (an input the stage needs has not arrived yet). */
    // Frame gate: false → the whole frame returns null (a late-bound input is still pending).
    ready?(): boolean
    /** Bookkeeping before any gate: pointer smoothing, activity flags. */
    tick?(f: GridFrame): void
    /** Return true to skip the whole frame. The last published texture stays on screen. */
    skip?(f: GridFrame): boolean
    /** Add this stage's GPU passes and value writes to the frame. */
    emit?(f: GridFrame, nodes: ComputeStep[]): void
}

sim.grids.GridSimConfig.text:
interface GridSimConfig {
    /** The textures the fragment samples, by the name it reads them under in `computeOutputs`. */
    // State/display textures, child RTT handles.
    outputs: Record<string, unknown>
    /** Receive the child's picture once it exists (it is allocated after the layer composes). */
    // Late input binding (child RTT → luma prepass, child-modulated kernels). Spread only if set.
    bindInputs?: (resolve: (key: string) => {texture: unknown} | undefined) => void
    /** Longest frame step accepted, in seconds. 0.016–0.05 keeps a tab switch from jumping the field. */
    clampDt: number
    /** What to do on a frame with no elapsed time: run anyway (default) or skip it. */
    // Liquify's guard.
    zeroDt?: 'run' | 'skip'
    /** The frame program, in order. */
    stages: GridStage[]
}

sim.grids.HostFrame.text:
interface HostFrame {
    /** Seconds since the last frame, never more than `clampDt`. */
    // Wall-clock delta (these sims ignore the renderer's deltaTime).
    dt: number
    now: number
    pointer: {x: number; y: number}
    frameParams: unknown
}

sim.grids.HostStep.text:
interface HostStep {
    name: string
    run(f: HostFrame): void | 'skip'
}

sim.fluids.FluidFrameParams.text:
interface FluidFrameParams {
    pointer?: PointerLike
    deltaTime?: number
    dimensions?: {width: number; height: number}
}

sim.fluids.FluidFrame.text:
interface FluidFrame {
    /** Seconds since the last frame, never more than `maxDeltaTime` (0.033 by default). */
    dt: number
    /** Wall-clock milliseconds this frame. */
    // `Date.now()` (wall-clock bookkeeping; the idle gates run on simulated `dt`).
    now: number
    /** The simulation's own clock: the sum of every `dt` so far. */
    // An init part may reset it (Fog's warm-up).
    readonly elapsed: number
    setElapsed(t: number): void
    /** The pointer this frame, when the config declared `pointer`. Null otherwise. */
    // The noun-owned tracker's sample. Ribbons own their own.
    ptr: PointerFrame | null
    /** A numeric prop's current value, or `fallback` when it is not a number this frame. */
    num(key: string, fallback: number): number
    /** Any prop's current value. */
    getCpuValue(key: string): unknown
    frameParams: FluidFrameParams
    /** Write the per-frame values directly, for a part that rewrites them between passes. */
    // Per-stamp rewrites inside ribbon thunks.
    writeParams(v: unknown): void
}

sim.fluids.FluidSetupCtx.text:
interface FluidSetupCtx {
    params: GpuFragmentParams
    root: FluidRoot
    /** Cells per side of the grid. */
    n: number
    buffers: {
        velA: unknown; velB: unknown; dyeA: unknown; dyeB: unknown
        pressure: unknown; divergence: unknown; maskBuf?: unknown
    }
    /** The buffer holding the per-frame values, for a part with its own resources. */
    paramsBuffer: unknown
    /** The resource group every solver pass runs on. */
    fluidBindGroup: unknown
    /** Turn a pass function into a runnable pass, on the fluid's resources unless another group is given. */
    pass(kernel: FluidKernel, bindGroup?: unknown): KitComputePipeline
}

sim.fluids.FluidEmitter.text:
interface FluidEmitter<TParams = unknown> {
    setup?(ctx: FluidSetupCtx): void
    /** Bookkeeping before the idle gate: sample the pointer, drift a color cycle, mark activity. */
    tick?(f: FluidFrame): void
    /** Return true to skip the whole frame. The settled field stays on screen. */
    skip?(f: FluidFrame): boolean
    /** Add this frame's injection passes. They run before the solve. */
    emit?(f: FluidFrame, nodes: ComputeStep[], values: TParams): void
}

sim.fluids.FluidInitIo.text:
interface FluidInitIo<TParams> {
    nodes: ComputeStep[]
    writeParams(v: TParams): ComputeStep
    solve(nodes: ComputeStep[], jacobiIters: number): void
}

sim.fluids.FluidInitPart.text:
interface FluidInitPart<TParams = unknown> {
    setup?(ctx: FluidSetupCtx): void
    /** Return true when the field must be (re)seeded this frame. */
    stale(f: FluidFrame): boolean
    run(f: FluidFrame, io: FluidInitIo<TParams>): void
}

sim.fluids.FluidContainerParts.text:
interface FluidContainerParts {
    /** The pass that writes the inside/outside mask, run after the values write and before injection. */
    maskPass: KitComputePipeline
    /** Extra outputs for the fragment. */
    // The volumetric field texture.
    outputs?: Record<string, unknown>
    /** Passes that run first each frame, even on a frame too short to solve. */
    // The volumetric field pre-march. They run FIRST, and they are what a sub-millisecond frame
    // still returns — a pending march is never dropped.
    preFrame?(frameParams: unknown): ComputeStep[] | null
}

sim.fluids.FluidSimConfig.text:
interface FluidSimConfig<TParams> {
    /** Cells per side of the grid. 256 is the usual choice. */
    // Structural — the kernels are baked against it.
    resolution: number
    /** The layout naming the fluid's buffers. It must use the solver's entry names. */
    // The scaffolds/fluids entry-name contract: velA, velB, dyeA, dyeB, pressure, divergence, params (+ maskBuf).
    layout: unknown
    /** The layout of the output pass: the dye buffer read-only plus the output texture. */
    // `dyeA` read-only + `outTex`.
    outputLayout: unknown
    /** The schema of the per-frame values your passes read. The engine owns the buffer. */
    paramsSchema: unknown
    /** The solver's passes and how many pressure iterations to run per solve. 10 is the norm. */
    solver: {kernels: StableFluidsKernels; jacobiIters: number}
    /** The pass that turns dye into the output texture, and the name the fragment reads it under. */
    output: {kernel: FluidKernel; key: string}
    /** How the values reach the GPU: written at once (default), or queued in order with the passes. Use `'thunk'` with `seededFieldInit`, whose warm-up queues its own writes. */
    write?: 'direct' | 'thunk'
    /** Track the pointer for a cursor force. Stroke emitters built with `cursorRibbon` track their own. */
    pointer?: PointerVelocityTrackerOptions
    /** A shape the fluid is confined to. */
    // Allocates `maskBuf`, dispatches its mask pass every frame.
    container?: {setup(ctx: FluidSetupCtx): FluidContainerParts}
    /** How the field starts. Omit to start empty. */
    init?: FluidInitPart<TParams>
    /** What injects dye and momentum each frame. */
    inject?: FluidEmitter<TParams>[]
    /** Passes run before and after every solve. */
    solve?: FluidSolveStage[]
    /** The values your passes read this frame, built from the clock, the pointer and your props. */
    // The per-frame params derivation — the one runtime surface.
    values(f: FluidFrame): TParams
    /** Longest frame step accepted, in seconds. Default 0.033. */
    maxDeltaTime?: number
}

sim.fluids.CursorRibbonSpec.text:
interface CursorRibbonSpec<TPrepared> {
    /** Distance between stamps, in uv. Half the brush radius reads continuous. */
    stepSize: number
    /** Most stamps in one frame, so a fast flick cannot run away. */
    maxSteps: number
    /** A per-stamp payload prepared in stamp order, with `t` from 0 to 1 along the stroke. */
    // Advanced at BUILD time in stamp order (InkFlow's color cycle).
    prepare?: (t: number) => TPrepared
    /** Write the values for one stamp at `posX, posY` (grid cells) right before its pass runs. */
    // Runs in a thunk right before that stamp's dispatch.
    write: (posX: number, posY: number, t: number, prepared: TPrepared) => void
}

sim.feedback.FeedbackSimConfig.text:
interface FeedbackSimConfig<TParams, TGroups> {
    /** Cells per side of the square state texture. 512–768 reads sharp on most canvases. */
    // State + display resolution per axis (square — both current consumers' shape).
    size: number
    /** Storage precision. `rgba16float` is enough for color; `rgba32float` for exact positions. */
    format: 'rgba16float' | 'rgba32float'
    /** Extra textures that keep a previous and a current side, swapped together with the state. */
    // TimeTrail's prev-live copy. A `[1, 1]` stub fills a slot a disabled kernel variant never touches.
    extraSlots?: Record<string, SimSize>
    /** Extra textures with no previous side. */
    textures?: Record<string, SimSize>
    /** A prop that scales the clock. 0 freezes the simulation, 2 runs it twice as fast. */
    speedProp?: string
    /** Longest frame step accepted, in seconds. Default 0.05. Keeps a tab switch from jumping the state. */
    maxDeltaTime?: number
    /** The schema of the per-frame values your step reads. The engine owns the buffer. */
    paramsSchema: unknown
    /**
     * Wire your layout for one direction of the swap: `read` is last frame's state, `write` is
     * this frame's. Called twice, once per direction, after the child's picture exists.
     */
    bindGroups: (ctx: FeedbackBindContext, read: SimSlot, write: SimSlot) => TGroups
    /** Wire resources that do not depend on the swap direction. Called once. */
    staticGroups?: (ctx: FeedbackBindContext) => unknown
    /**
     * The rule: one step function that reads `read`, writes `write` and the display copy.
     * Pick the variant inside the build callback when a compile-time prop changes it.
     */
    // ONE kernel per step, compile-time variant selected in the build callback. Splitting a step
    // into several kernels is a different simulation (and different WGSL); a shader that needs a
    // multi-dispatch step should not ride this noun's default frame.
    step: FeedbackKernel
    /** Return true to skip this frame. The last state stays on screen and nothing swaps. */
    skip?: (t: SimTick<TGroups, unknown>) => boolean
    /** The values your step reads this frame, built from the clock and your props. */
    // The per-frame params derivation — the one runtime surface. Written before the dispatch.
    values: (t: SimTick<TGroups, unknown>) => TParams
    /** Extra outputs for the fragment beyond `childTexture` and `display`. */
    outputs?: Record<string, unknown>
}

sim.agents.RenderAgentsPipelines.text:
interface RenderAgentsPipelines {
    splat: AgentPipelineSpec
    resolve: AgentPipelineSpec
}

sim.agents.AgentSimBaked.text:
interface AgentSimBaked {
    /** Every step by name: the spawn, the physics, the splat, the resolve. */
    pipelines: Record<string, AgentPipelineSpec>
    /** The steps that run each frame, in order (keys of `pipelines`). */
    program: readonly string[]
    /** The spawn step, run once before the first frame and again when `reseed` changes. */
    initStep?: string
    /** Override the output size decided at composition (an aspect-fitted target). */
    outputSize?: [number, number]
    /** A second resource group for every step marked `extra` (a shape's own distance field). */
    extraBindGroup?: unknown
    /** Resources ready now for the keys in `externalKeys` (a solver's texture created in `bake`). */
    bindNow?: Record<string, unknown>
    /** Anything `frame` needs from composition: a solver, a per-shape resolver. */
    setup?: unknown
}

sim.agents.AgentSimFragmentConfig.text:
interface AgentSimFragmentConfig {
    /** The output the fragment samples over the full canvas. */
    // rgba16f is filterable — one bilinear tap.
    output: string
    /** What to show without a GPU: nothing, or the child untouched. */
    fallback: 'transparent' | 'child'
    /** Combine the sampled picture with something else, such as laying it over the child. */
    compose?: (field: Expr, params: GpuFragmentParams) => Expr
}

sim.agents.AgentSimConfig.text:
interface AgentSimConfig<TParams extends AnyWgslStruct> {
    /** The layout naming the per-agent buffers, the accumulators, the values and the output texture. */
    layout: AgentSystemConfig<TParams>['layout']
    /** The schema of the per-frame values the steps read. */
    params: TParams
    /** How many agents the buffers hold. The count prop can be anything up to it. */
    maxAgents: number
    /** A lower effective count on phones and tablets. The prop's range is unchanged. */
    countCap?: DeviceTier
    /** The output texture: its layout key, the name the fragment reads it under, its size and format. */
    output: AgentSystemConfig<TParams>['output']
    /** Layout keys filled later, through `childTexture` or `bake.bindNow`. */
    externalKeys?: readonly string[]
    /** Read the child as a texture and bind it to this layout key once it exists. */
    // ParticleField.
    childTexture?: {externalKey: string}
    /** Assemble the steps once per composition, from compile-time props. Return null to run nothing. */
    bake: (params: GpuFragmentParams) => AgentSimBaked | null
    /** Build the once-per-frame program: write the values, then return `sys.frame(...)`. */
    // Usually via `sys.frame(...)`, prepending any extra passes the shader owns.
    frame: (
        sys: AgentSystem<TParams>,
        params: GpuFragmentParams,
        setup: unknown,
    ) => (frameParams: unknown) => ComputeStep[] | null
    fragment: AgentSimFragmentConfig
}

sim.agents.AgentSimSpread.text:
interface AgentSimSpread {
    compute: GpuComputeNode
    gpu: {fragment: (params: GpuFragmentParams) => Expr}
}

